import { DailySummary } from "./crossModuleSummary";

export interface MeasurementContext {
  userName?: string;
  userGender?: 'male' | 'female';
  summary: DailySummary;
  pulse: number | null;
  weight: number | null;
  initialWeight: number | null;
  weightDelta: number | null;
  tonusEnergy: string | null;
  tonusMood: string | null;
  tonusWellbeing: string | null;
  systolic: number | null;
  diastolic: number | null;
}

export const numberToText = (num: number, type: 'pulse' | 'weight' | 'delta'): string => {
  const noun = (n: number, forms: [string, string, string]): string => {
    const tens = n % 100;
    const unit = n % 10;
    return tens >= 11 && tens <= 14 ? forms[2] : unit === 1 ? forms[0] : unit >= 2 && unit <= 4 ? forms[1] : forms[2];
  };
  if (!Number.isFinite(num)) return '';
  if (type === 'pulse') {
    const n = Math.round(Math.abs(num));
    return `${n} ${noun(n, ['удар', 'удара', 'ударов'])} в минуту`;
  }
  const total = Math.round(Math.abs(num) * 1000);
  const kg = Math.floor(total / 1000);
  const g = total % 1000;
  if (type === 'delta' && kg === 0) return `${g} ${noun(g, ['грамм', 'грамма', 'граммов'])}`;
  return `${kg} ${noun(kg, ['килограмм', 'килограмма', 'килограммов'])}${g ? ` ${g} ${noun(g, ['грамм', 'грамма', 'граммов'])}` : ''}`;
};

const bp = (c: MeasurementContext): string => `${c.systolic}/${c.diastolic}`;
const pp = (c: MeasurementContext): number => (c.systolic ?? 0) - (c.diastolic ?? 0);
const change = (c: MeasurementContext): string => c.weightDelta === null ? '' : numberToText(Math.abs(c.weightDelta), 'delta');
const pulseContext = (c: MeasurementContext): string => c.pulse === null ? '' : ` Пульс ${c.pulse} уд/мин.`;
const movementContext = (c: MeasurementContext): string => {
  const value = c.summary.movement.activeMin;
  return value >= 30 ? `За сегодня записано ${value} мин движения: цель Системы 30 мин выполнена.` : `Сегодня записано ${value} мин движения: до цели 30 мин осталось ${30 - value} мин.`;
};
const waterContext = (c: MeasurementContext): string => {
  const { amount, goal } = c.summary.water;
  return `По дневнику воды ${amount} из ${goal} мл; это учёт жидкости, не диагноз обезвоживания.`;
};
const digestionContext = (c: MeasurementContext): string => {
  if (c.summary.digestion.status === 'constipation') return 'В «Организме» отмечен плотный стул; при повышенном АД избегай натуживания.';
  if (c.summary.digestion.status === 'diarrhea') return 'В «Организме» отмечен жидкий стул; при слабости и низком АД важна оценка потерь жидкости.';
  return 'Для этой записи пищеварение не даёт отдельного сигнала.';
};
