export const getRandomPhrase = (category: keyof typeof MEASUREMENT_PHRASES, ctx: MeasurementContext): string => {
  const phrases = MEASUREMENT_PHRASES[category];
  if (!phrases || phrases.length === 0) return "";
  const seed = `${category}|${ctx.systolic ?? ''}|${ctx.diastolic ?? ''}|${ctx.pulse ?? ''}|${ctx.weight ?? ''}|${ctx.weightDelta ?? ''}|${ctx.tonusEnergy ?? ''}|${ctx.tonusMood ?? ''}|${ctx.tonusWellbeing ?? ''}|${ctx.summary.movement.activeMin}|${ctx.summary.water.amount}`;
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i += 1) hash = Math.imul(hash ^ seed.charCodeAt(i), 16777619);
  return phrases[(hash >>> 0) % phrases.length](ctx);
};
